def read(path):
    raw = path.read_bytes()
    return raw.decode('utf-16' if raw[:2] in (b'\xff\xfe', b'\xfe\xff') else 'utf-8-sig')


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_bytes(path, raw):
    if not path.resolve().is_relative_to(ROOT) or path.exists():
        raise RuntimeError(f'Output refused: {path}')
    temp = path.with_name(path.name + '.tmp')
    with temp.open('xb') as stream:
        stream.write(raw)
    if temp.stat().st_size != len(raw) or temp.read_bytes() != raw:
        raise RuntimeError(f'Incomplete output: {temp}')
    temp.rename(path)


def write_new(path, value):
    write_bytes(path, value.encode('utf-8'))


def runs(module):
    records = []
    for meta in sorted(ROOT.glob(module + '.*.json')):
        data = json.loads(read(meta))
        log = ROOT / data['log']
        output = read(log)
        rejected = data['exit_code'] != 0 or bool(re.search(r'\b(error|warning)(?:\([^\n]*?\))?:', output))
        label = ('failed_compile' if data['exit_code'] else
                 'rejected_warning')
        archive = log.with_name(log.stem + '.' + label + '.log') if rejected else None
        records.append((meta, data, log, output, archive))
    if CLEAN_MANIFEST.exists():
        clean = json.loads(read(CLEAN_MANIFEST))
        for step in clean['steps']:
            if step['module'] != module:
                continue
            meta = Path(step['metadata'])
            data = json.loads(read(meta))
            log = Path(data['log'])
            output = read(log)
            if (data['exit_code'] != 0 or
                    re.search(r'\b(error|warning)(?:\([^\n]*?\))?:', output)):
                raise RuntimeError('A rejected run was marked as a clean final step')
            records.append((meta, data, log, output, None))
    return records


def preserve_attempts():
    for module in MODULES:
        for _, _, log, _, archive in runs(module):
            if archive is not None:
                if archive.exists():
                    if archive.read_bytes() != log.read_bytes():
                        raise RuntimeError(f'Archive mismatch: {archive}')
                else:
                    write_bytes(archive, log.read_bytes())


def axiom_rows(output):
    pattern = (
        r"'([^']+)' (?:depends on axioms: \[([^\]]*)\]"
        r"|does not depend on any axioms)"
    )
    result = []
    for match in re.finditer(pattern, output):
        names = match.group(2) or ''
        result.append({
            'declaration': match.group(1),
            'axioms': [name.strip() for name in names.split(',') if name.strip()],
        })
    if any(not set(row['axioms']) <= ALLOWED for row in result):
        raise RuntimeError('Unexpected axiom dependency')
    return result


def inspect_module(module):
    source = ROOT / (module + '.lean')
    code = read(source)
    namespaces = re.findall(r'^namespace ([\w.]+)', code, re.M)
    if len(namespaces) != 1:
        raise RuntimeError(f'Unexpected namespace structure: {module}')
    namespace = namespaces[0]
    if namespace != 'ChatgptAudit.Observable035':
        raise RuntimeError(f'Unexpected namespace: {module}')
    if re.search(r'\b(sorry|admit|axiom)\b', code):
        raise RuntimeError(f'Forbidden declaration: {source}')
    declarations = re.findall(r'^(theorem|def)\s+([\w.]+)', code, re.M)
    theorems = [name for kind, name in declarations if kind == 'theorem']
    prints = re.findall(r'^#print axioms ([\w.]+)', code, re.M)
    if not set(theorems) <= set(prints) or len(prints) != len(set(prints)):
        raise RuntimeError(f'Theorem print coverage mismatch: {module}')
    if not set(prints) <= {name for _, name in declarations}:
        raise RuntimeError(f'Unknown printed declaration: {module}')
    attempts = runs(module)
    candidates = [r for r in attempts if r[1]['exit_code'] == 0 and r[1]['source_stable']
                  and r[1]['proof_sha256'].lower() == digest(source) and r[4] is None
                  and r[1].get('fresh_clean_build') and r[1].get('inputs_stable')]
    if not candidates:
        raise RuntimeError(f'No clean compilation for exact final source: {module}')
    meta, data, log, output, _ = candidates[-1]
    if 'sorryAx' in output:
        raise RuntimeError(f'Unproved final dependency: {module}')
    axioms = axiom_rows(output)
    if sorted(row['declaration'] for row in axioms) != sorted(namespace + '.' + name for name in prints):
        raise RuntimeError(f'Qualified axiom names mismatch: {module}')
    if instance_census(code)['anonymous']:
        raise RuntimeError(f'Anonymous instance in new module: {module}')
    paths = {source, Path(data['source']), Path(data['olean'])}
    paths.update(ROOT.glob(module + '.lean.bak_*'))
    history = []
    source_versions = {digest(source)} | {digest(p) for p in ROOT.glob(module + '.lean.bak_*')}
    for m, d, l, out, archive in attempts:
        if d['proof_sha256'].lower() not in source_versions or not d['source_stable']:
            raise RuntimeError(f'Historical source missing or unstable: {m}')
        paths.update([m, l])
        if archive is not None:
            if not archive.exists() or archive.read_bytes() != l.read_bytes():
                raise RuntimeError(f'Failed attempt not preserved: {l}')
            paths.add(archive)
        history.append({'metadata': str(m), 'log': str(l), 'exit_code': d['exit_code'],
                        'record_kind': 'bench_interruption_note' if out.startswith('BENCH INTERRUPTION RECORD') else 'lean_compiler_output',
                        'source_sha256': d['proof_sha256'].lower(),
                        'rejected_copy': str(archive) if archive else None,
                        'issues': [line for line in out.splitlines()
                                   if re.search(r'\b(error|warning)(?:\([^\n]*?\))?:', line)]})
    return {'module': module, 'namespace': namespace, 'instance_census': instance_census(code),
            'theorems': len(theorems), 'printed_definitions': len(prints)-len(theorems),
            'helper_definitions_not_separately_printed': [n for k, n in declarations if k == 'def' and n not in prints],
            'final_metadata': str(meta), 'final_log': str(log), 'axioms': axioms, 'attempts': history}, paths



CLEAN_MANIFEST = ROOT / 'CONTINUACAO035_CLEAN_BUILD.json'
BASELINE = ['CentralizerDensity', 'LikelihoodDensityLog', 'DensityStateUniqueness',
            'SitePhaseCovariance', 'CentralizerPhaseOrbit', 'AngularScreenMetric',
            'AngularAreaObservability']


def instance_census(code):
    prefix = r'^[ \t]*(?:(?:local|scoped|private|protected|noncomputable)\s+)*instance'
    anonymous = re.findall(prefix + r'\s*(?=[(:{])', code, re.M)
    named = re.findall(prefix + r'\s+([A-Za-z_][\w.]*)', code, re.M)
    all_instances = re.findall(prefix + r'\b', code, re.M)
    if len(anonymous) + len(named) != len(all_instances):
        raise RuntimeError('Unsupported instance syntax in the source census')
    return {'anonymous': len(anonymous), 'named': named}


def clean_build():
    data = json.loads(read(CLEAN_MANIFEST))
    if (data['status'] != 'PASS' or data['modules'] != MODULES or
            set(data['baseline_modules']) != set(BASELINE) or
            len(data['build_order']) != 12 or
            set(data['build_order']) != set(MODULES + BASELINE) or
            data['anonymous_instances_remaining'] != 0 or
            not data['fresh_clean_build']):
        raise RuntimeError('Invalid clean-build declaration')
    directory = Path(data['clean_directory']).resolve()
    if not directory.is_relative_to(ROOT) or directory == ROOT:
        raise RuntimeError('Clean build escaped the authorized workspace')
    for item in data['files']:
        path = Path(item['path'])
        if path.stat().st_size != item['bytes'] or digest(path) != item['sha256']:
            raise RuntimeError(f'Clean-build custody mismatch: {path}')
    sources = {row['module']: row for row in data['sources']}
    if len(sources) != 12 or set(sources) != set(MODULES + BASELINE):
        raise RuntimeError('Clean source set mismatch')
    for name, row in sources.items():
        source = Path(row['source'])
        original = ROOT / (name + '.lean')
        if (not source.resolve().is_relative_to(directory) or
                digest(source) != row['proof_sha256'] or
                digest(original) != row['original_sha256'] or
                instance_census(read(source))['anonymous'] != 0):
            raise RuntimeError(f'Clean source mismatch: {name}')
        if name in MODULES and source.read_bytes() != original.read_bytes():
            raise RuntimeError(f'Current source was transposed in clean build: {name}')
        if name in BASELINE:
            if instance_census(read(original))['named']:
                raise RuntimeError('Baseline with pre-existing named instances needs explicit handling')
            erased = re.sub(
                rb'(?m)^([ \t]*(?:(?:local|scoped|private|protected|noncomputable)[ \t]+)*instance[ \t]+)'
                rb'[A-Za-z_][A-Za-z_0-9.]*[ \t]+(?=[(:{])',
                rb'\1', source.read_bytes())
            if erased != original.read_bytes():
                raise RuntimeError(f'Baseline change exceeds inserted instance names: {name}')
    steps = data['steps']
    if (len(steps) != 13 or
            [row['module'] for row in steps] != data['build_order'] + [data['integration_module']]):
        raise RuntimeError('Clean compilation order mismatch')
    for row in steps:
        metadata_path = Path(row['metadata'])
        meta = json.loads(read(metadata_path))
        source = Path(meta['source'])
        log = Path(meta['log'])
        olean = Path(meta['olean'])
        if any(not p.resolve().is_relative_to(directory) for p in
               [metadata_path, source, log, olean]):
            raise RuntimeError('Clean step path escaped the clean directory')
        if source.name != row['module'] + '.lean' or olean.name != row['module'] + '.olean':
            raise RuntimeError('Clean step source or output module name mismatch')
        if row['module'] in sources:
            expected = sources[row['module']]
            if (source.resolve() != Path(expected['source']).resolve() or
                    meta['proof_sha256'].lower() != expected['proof_sha256'].lower()):
                raise RuntimeError('Clean source map is not linked to the compiled step')
        output = read(log)
        if (meta['module'] != row['module'] or meta['exit_code'] != 0 or
                meta.get('passed') is not True or meta.get('axiom_coverage_exact') is not True or
                meta['inputs_before'] != meta['inputs_after'] or
                not meta['source_stable'] or not meta['inputs_stable'] or
                not meta['fresh_clean_build'] or
                digest(source) != meta['proof_sha256'].lower() or
                digest(log) != meta['log_sha256'].lower() or
                digest(Path(meta['olean'])) != meta['olean_sha256'].lower() or
                'sorryAx' in output or
                re.search(r'\b(error|warning)(?:\([^\n]*?\))?:', output)):
            raise RuntimeError(f'Clean compilation evidence invalid: {row["module"]}')
        actual_axioms = axiom_rows(output)
        if actual_axioms != meta['axiom_rows']:
            raise RuntimeError('Clean axiom rows differ from the compiler output')
        if [item['declaration'] for item in actual_axioms] != meta['expected_axiom_rows']:
            raise RuntimeError('Clean axiom print coverage is inconsistent')
        source_text = read(source)
        source_prints = re.findall(r'^#print axioms ([\w.]+)', source_text, re.M)
        source_namespaces = re.findall(r'^namespace ([\w.]+)', source_text, re.M)
        if row['module'] in sources:
            if len(source_namespaces) != 1:
                raise RuntimeError('Clean source namespace ambiguity')
            qualified = [source_namespaces[0] + '.' + name for name in source_prints]
            if qualified != meta['expected_axiom_rows']:
                raise RuntimeError('Clean expected axiom list differs from source prints')
        elif source_prints:
            raise RuntimeError('Unexpected proof prints in the import-only module')
    integration = json.loads(read(Path(steps[-1]['metadata'])))
    imports = re.findall(r'^import\s+(\S+)', read(Path(integration['source'])), re.M)
    if len(imports) != 12 or set(imports) != set(MODULES + BASELINE):
        raise RuntimeError('Integration source does not import the complete clean batch')
    return data


def clean_summary():
    data = clean_build()
    return {'manifest': str(CLEAN_MANIFEST), 'manifest_sha256': digest(CLEAN_MANIFEST),
            'directory': data['clean_directory'], 'modules': data['modules'],
            'baseline_modules': data['baseline_modules'],
            'build_order': data['build_order'],
            'integration_module': data['integration_module'],
            'anonymous_instances_remaining': 0, 'fresh_clean_build': True}


